INSERT INTO `cms_pages` VALUES (1,'about-us','About Us','<h2>Mumbai\'s trusted battery delivery service</h2>\n<p>Trikuti Battery delivers genuine automotive batteries to your doorstep across Mumbai, Thane and Navi Mumbai — with free same-day or next-day delivery for most pincodes.</p>\n\n<h3>Why choose us</h3>\n<ul>\n<li><strong>Genuine batteries only</strong> — sourced directly from authorised dealers of Exide, Amaron, SF Sonic and other top brands</li>\n<li><strong>Same or next-day delivery in Mumbai</strong> — orders confirmed today are delivered the same day or the next working day across Mumbai City and Suburbs</li>\n<li><strong>Free installation</strong> — our technician installs the battery and takes your old battery away</li>\n<li><strong>Old battery exchange</strong> — get up to ₹800 off when you exchange your old battery</li>\n<li><strong>Full manufacturer warranty</strong> — every battery comes with the brand\'s official warranty (24-48 months)</li>\n</ul>\n\n<h3>Service area</h3>\n<p>We currently deliver to:</p>\n<ul>\n<li><strong>Zone A (₹99, same or next day):</strong> Rabale · Airoli · Ghansoli · Kopar Khairane · Turbhe · Vashi · Sanpada · Juinagar · Nerul · Thane (West + East) · Kalwa · Mulund · Nahur · Bhandup · Kanjurmarg</li>\n<li><strong>Zone B (₹199, 1–2 business days):</strong> Mumbra · Diva · Dombivli (East + West) · Kalyan (East + West)</li>\n<li><strong>Free delivery</strong> on orders above ₹12,000 (both zones)</li>\n</ul>\n<p>Any pincode outside these zones is not currently served — we\'re focused on getting our home zones perfectly right first.</p>\n\n<h3>Payment options</h3>\n<p>Cash on Delivery is our primary option — pay when the battery is delivered to your doorstep. UPI (Google Pay / PhonePe / Paytm) accepted at delivery too.</p>','About Us | Mumbai Battery Store','About Us — Mumbai\'s trusted battery delivery service.',1,1,1,'2026-04-30 07:23:10','2026-08-04 01:38:13'),(2,'contact-us','Contact Us','<h2>Get in touch</h2>\n<p>We\'re here to help with your battery purchase, installation, or warranty questions.</p>\n\n<div style=\"display:grid;gap:1rem;grid-template-columns:1fr 1fr;margin:1.5rem 0;\">\n  <div>\n    <h3>📞 Phone</h3>\n    <p><strong>+91 9920971479</strong><br>\n    <small>Monday – Saturday, 9am to 8pm</small></p>\n  </div>\n  <div>\n    <h3>💬 WhatsApp</h3>\n    <p><strong>+91 9920971479</strong><br>\n    <small>Quick replies on quotes and order status</small></p>\n  </div>\n  <div>\n    <h3>📧 Email</h3>\n    <p><a href=\"mailto:vbs622026@gmail.com\">vbs622026@gmail.com</a><br>\n    <small>Replies within 4 working hours</small></p>\n  </div>\n  <div>\n    <h3>📍 Address</h3>\n    <p>Trikuti Battery<br>\n    R-30, MIDC Area Rd, MIDC Industrial Area<br>\n    Rabale, Navi Mumbai, Maharashtra 400701</p>\n  </div>\n</div>\n\n<h3>Service hours</h3>\n<ul>\n<li>Mon – Sat: 9:00 AM – 8:00 PM</li>\n<li>Sunday: Closed (emergency orders via WhatsApp)</li>\n</ul>\n\n<h3>Delivery area</h3>\n<p>All Mumbai (400001 – 400104), Thane (400601 – 400615) and Navi Mumbai (400701 – 400710). Check delivery to your pincode on any product page.</p>','Contact Us | Mumbai Battery Store','Contact Us — Mumbai\'s trusted battery delivery service.',1,1,2,'2026-04-30 07:23:10','2026-07-01 06:44:21'),(3,'privacy-policy','Privacy Policy','<p>We respect your privacy. <em>Replace this with your real privacy policy.</em></p>','Privacy Policy | Mumbai Battery Store','Privacy Policy — Mumbai\'s trusted battery delivery service.',1,1,3,'2026-04-30 07:23:10','2026-06-15 01:47:11'),(4,'terms-and-conditions','Terms & Conditions','<p><em>Replace this with your real terms and conditions before going live.</em></p>','Terms & Conditions | Mumbai Battery Store','Terms & Conditions — Mumbai\'s trusted battery delivery service.',1,1,4,'2026-04-30 07:23:10','2026-06-15 01:47:11');
