INSERT INTO `faqs` VALUES (1,'Order','How long does delivery take?','Most metro pincodes get same-day or next-day delivery. Other locations take 2-4 business days.',1,1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(2,'Order','Can I cancel my order?','Yes, you can cancel from your account any time before the battery is dispatched.',4,1,'2026-04-30 07:23:10','2026-06-15 01:47:11'),(3,'Battery','What is old battery exchange?','You can return your old battery and get an exchange discount on the new battery.',3,1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(4,'Battery','How is the warranty period calculated?','Warranty starts from the date of delivery and is provided directly by the battery manufacturer (Exide, Amaron, etc.).',6,1,'2026-04-30 07:23:10','2026-06-15 01:47:11'),(5,'Payment','What payment methods are supported?','UPI, debit/credit cards, and Cash on Delivery.',5,1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(6,'Payment','Is COD available?','Yes, COD is available for orders below ₹20,000 in most pincodes.',6,1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(7,'Delivery','How fast is delivery in Mumbai?','For all Mumbai City and Suburbs pincodes (400001 – 400104), we deliver the same day or by the next working day. Thane and Navi Mumbai take 1–2 business days. Our team confirms the exact delivery slot when we call you back.',1,1,'2026-06-15 01:47:11','2026-08-04 01:12:56'),(8,'Delivery','Is delivery free?','Yes — free delivery across all Mumbai City and Suburbs pincodes. Thane and Navi Mumbai have a flat ₹99 delivery charge.',2,1,'2026-06-15 01:47:11','2026-06-15 01:47:11'),(9,'Delivery','Do you install the battery?','Yes, free installation is included with every battery delivery. Our technician will install the new battery and take your old one away.',3,1,'2026-06-15 01:47:11','2026-06-15 01:47:11'),(10,'Battery','How does old battery exchange work?','Add the exchange option when adding a battery to cart. Hand over your old battery to the technician during installation and get up to ₹800 off instantly.',5,1,'2026-06-15 01:47:11','2026-06-15 01:47:11'),(11,'Payment','What payment methods do you accept?','Cash on Delivery (COD) and UPI (Google Pay / PhonePe / Paytm) at the time of delivery. Our team confirms the final amount over a call before dispatch.',7,1,'2026-06-15 01:47:11','2026-07-31 04:46:45'),(12,'Payment','Is COD available across Mumbai?','Yes, COD is available for all serviceable pincodes including Mumbai, Thane and Navi Mumbai.',8,1,'2026-06-15 01:47:11','2026-07-31 04:46:45'),(13,'Delivery','How fast is delivery?','Zone A (Navi Mumbai + Thane + Mulund–Kanjurmarg belt): same or next working day. Zone B (Mumbra + Diva + Dombivli + Kalyan): 1–2 business days. Our team confirms the exact delivery slot when we call you back.',1,1,'2026-08-04 01:38:13','2026-08-04 01:38:13'),(14,'Delivery','How much does delivery cost?','Flat ₹99 in Zone A (our home base) and ₹199 in Zone B (Central Railway line). Free delivery on orders above ₹12,000. Any pincode outside these zones is not served yet.',2,1,'2026-08-04 01:38:13','2026-08-04 01:38:13');
