INSERT INTO `settings` VALUES (1,'general','site_name','Trikuti Battery','string','Site Name',1,'2026-04-30 07:23:10','2026-07-01 06:44:21'),(2,'general','site_tagline','Navi Mumbai\'s #1 battery delivery · Same or next-day across Mumbai metro','string','Site Tagline',1,'2026-04-30 07:23:10','2026-08-04 01:12:55'),(3,'general','support_email','vbs622026@gmail.com','string','Support Email',1,'2026-04-30 07:23:10','2026-06-15 01:47:10'),(4,'general','support_phone','+91 9920971479','string','Support Phone',1,'2026-04-30 07:23:10','2026-06-15 01:47:10'),(5,'general','whatsapp_number','+919920971479','string','WhatsApp Number',1,'2026-04-30 07:23:10','2026-06-15 01:47:10'),(6,'general','address','R-30, MIDC Area Rd, MIDC Industrial Area, Rabale, Navi Mumbai, Maharashtra 400701','text','Office Address',1,'2026-04-30 07:23:10','2026-06-15 01:47:10'),(7,'order','default_tax_percent','18','integer','Default GST % (CGST 9 + SGST 9)',0,'2026-04-30 07:23:10','2026-06-15 01:47:10'),(8,'order','default_delivery_charge','99','integer','Default Delivery Charge (₹) — Zone A pincodes',0,'2026-04-30 07:23:10','2026-08-04 01:38:12'),(9,'order','free_delivery_above','12000','integer','Free Delivery Above (₹) — only premium 100Ah+ orders qualify',0,'2026-04-30 07:23:10','2026-08-04 01:38:12'),(10,'order','cod_max_amount','20000','integer','Max COD Amount (₹)',0,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(11,'social','facebook','https://facebook.com/','string','Facebook URL',1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(12,'social','instagram','https://instagram.com/','string','Instagram URL',1,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(13,'seo','default_meta_title','Buy Car Batteries Online in Mumbai — Same or Next-day Delivery','string','Default Meta Title',0,'2026-04-30 07:23:10','2026-08-04 01:12:55'),(14,'seo','default_meta_description','Mumbai\'s trusted battery delivery service. Buy genuine Exide and Amaron car batteries with same or next-day delivery, free installation and old battery exchange across Mumbai, Thane and Navi Mumbai.','text','Default Meta Description',0,'2026-04-30 07:23:10','2026-08-04 01:12:55'),(15,'payment','cod_enabled','1','boolean','Enable COD',0,'2026-04-30 07:23:10','2026-04-30 07:23:10'),(16,'payment','upi_enabled','0','boolean','Enable UPI (requires Razorpay)',0,'2026-04-30 07:23:10','2026-07-01 06:44:21'),(17,'payment','card_enabled','0','boolean','Enable Card (requires Razorpay)',0,'2026-04-30 07:23:10','2026-07-01 06:44:21'),(18,'seo','google_analytics_id','','string','Google Analytics 4 ID (G-XXXXXXX)',0,'2026-07-01 07:01:59','2026-07-01 07:01:59'),(19,'seo','google_search_console','','string','Google Search Console verification token (content of google-site-verification meta)',0,'2026-07-01 07:01:59','2026-07-01 07:01:59'),(20,'seo','google_tag_manager_id','','string','Google Tag Manager container ID (GTM-XXXXXXX)',0,'2026-07-01 07:01:59','2026-07-01 07:01:59'),(21,'seo','facebook_pixel_id','','string','Facebook / Meta Pixel ID',0,'2026-07-01 07:01:59','2026-07-01 07:01:59'),(22,'seo','bing_verification','','string','Bing Webmaster verification token',0,'2026-07-01 07:01:59','2026-07-01 07:01:59');
